	'messages:apierror-cannotreauthenticate' => 'en:This action is not available as your identity cannot be verified.',
	'messages:apierror-cannotviewtitle' => 'en:You are not allowed to view $1.',
	'messages:apierror-cantblock-email' => 'en:You don\'t have permission to block users from sending email through the wiki.',
	'messages:apierror-cantblock' => 'en:You don\'t have permission to block users.',
	'messages:apierror-cantchangecontentmodel' => 'en:You don\'t have permission to change the content model of a page.',
	'messages:apierror-canthide' => 'en:You don\'t have permission to hide usernames from the block log.',
